using System.IO;
using System.Text;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace MooView;

public static class Imaging
{
    public static readonly HashSet<string> Extensions = new(StringComparer.OrdinalIgnoreCase) { ".jpg", ".jpeg", ".png", ".bmp", ".gif", ".tif", ".tiff", ".ico", ".wdp", ".jxr", ".webp" };
    public static BitmapSource Load(string path, int decode = 0) { using var s = File.OpenRead(path); var b = new BitmapImage(); b.BeginInit(); b.CacheOption = BitmapCacheOption.OnLoad; if (decode > 0) b.DecodePixelWidth = decode; b.StreamSource = s; b.EndInit(); b.Freeze(); return b; }
    public static BitmapSource Transform(BitmapSource b, double angle, double sx = 1, double sy = 1) { var group = new TransformGroup(); group.Children.Add(new ScaleTransform(sx, sy)); group.Children.Add(new RotateTransform(angle)); var v = new TransformedBitmap(b, group); v.Freeze(); return v; }
    public static byte[] ToneLut(double black, double white, double gamma, IReadOnlyList<Point> points) { var lut = new byte[256]; for (int i = 0; i < 256; i++) { double x = Math.Pow(Math.Clamp((i - black) / Math.Max(1, white - black), 0, 1), 1 / Math.Max(.1, gamma)); int k = 0; while (k < points.Count - 2 && x > points[k + 1].X) k++; var a = points[k]; var b = points[k + 1]; double y = a.Y + (b.Y - a.Y) * (x - a.X) / Math.Max(.00001, b.X - a.X); lut[i] = (byte)Math.Round(Math.Clamp(y, 0, 1) * 255); } return lut; }
    public static BitmapSource Adjust(BitmapSource source, byte[] lut) { var b = new FormatConvertedBitmap(source, PixelFormats.Bgra32, null, 0); int stride = b.PixelWidth * 4; var bytes = new byte[stride * b.PixelHeight]; b.CopyPixels(bytes, stride, 0); for (int i = 0; i < bytes.Length; i += 4) { bytes[i] = lut[bytes[i]]; bytes[i + 1] = lut[bytes[i + 1]]; bytes[i + 2] = lut[bytes[i + 2]]; } var result = BitmapSource.Create(b.PixelWidth, b.PixelHeight, 96, 96, PixelFormats.Bgra32, null, bytes, stride); result.Freeze(); return result; }
    public static BitmapEncoder Encoder(string ext) => ext.ToLowerInvariant() switch { ".jpg" or ".jpeg" => new JpegBitmapEncoder { QualityLevel = 95 }, ".bmp" => new BmpBitmapEncoder(), ".tif" or ".tiff" => new TiffBitmapEncoder(), ".gif" => new GifBitmapEncoder(), _ => new PngBitmapEncoder() };
    public static void Save(BitmapSource b, string path) { if (Path.GetExtension(path).Equals(".jpg", StringComparison.OrdinalIgnoreCase) || Path.GetExtension(path).Equals(".jpeg", StringComparison.OrdinalIgnoreCase)) { var v = new DrawingVisual(); using (var c = v.RenderOpen()) { c.DrawRectangle(Brushes.White, null, new Rect(0, 0, b.PixelWidth, b.PixelHeight)); c.DrawImage(b, new Rect(0, 0, b.PixelWidth, b.PixelHeight)); } var flat = new RenderTargetBitmap(b.PixelWidth, b.PixelHeight, 96, 96, PixelFormats.Pbgra32); flat.Render(v); b = flat; } var e = Encoder(Path.GetExtension(path)); e.Frames.Add(BitmapFrame.Create(b)); string temp = path + "." + Guid.NewGuid().ToString("N") + ".tmp"; try { using (var f = File.Create(temp)) e.Save(f); File.Move(temp, path, true); } finally { if (File.Exists(temp)) File.Delete(temp); } }
    public static Brush Background(bool checker, string color, bool dark) { if (!checker) return new SolidColorBrush((Color)ColorConverter.ConvertFromString(color)); var g = new DrawingGroup(); g.Children.Add(new GeometryDrawing(new SolidColorBrush(dark ? Color.FromRgb(44, 49, 46) : Color.FromRgb(218, 222, 216)), null, new RectangleGeometry(new Rect(0, 0, 24, 24)))); var brush = new SolidColorBrush(dark ? Color.FromRgb(54, 59, 56) : Color.FromRgb(231, 234, 227)); g.Children.Add(new GeometryDrawing(brush, null, new RectangleGeometry(new Rect(0, 0, 12, 12)))); g.Children.Add(new GeometryDrawing(brush, null, new RectangleGeometry(new Rect(12, 12, 12, 12)))); return new DrawingBrush(g) { TileMode = TileMode.Tile, Viewport = new Rect(0, 0, 24, 24), ViewportUnits = BrushMappingMode.Absolute, Stretch = Stretch.None }; }
    public static string Metadata(string path, BitmapSource? b) { var sb = new StringBuilder(); var f = new FileInfo(path); sb.AppendLine(f.Name); sb.AppendLine(path); if (b != null) sb.AppendLine($"\n{b.PixelWidth:N0} × {b.PixelHeight:N0} px\n{b.DpiX:0.#} × {b.DpiY:0.#} dpi"); sb.AppendLine($"{f.Length:N0} bytes\n수정: {f.LastWriteTime:yyyy-MM-dd HH:mm:ss}"); try { using var s = File.OpenRead(path); var d = BitmapDecoder.Create(s, BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad); sb.AppendLine($"프레임: {d.Frames.Count}"); if (d.Frames[0].Metadata is BitmapMetadata m) { sb.AppendLine($"\n카메라: {m.CameraManufacturer} {m.CameraModel}\n촬영일: {m.DateTaken}\n제목: {m.Title}\n저작권: {m.Copyright}"); var seen = new HashSet<string>(); Walk(m, "", sb, seen, 0); } } catch (Exception e) { sb.AppendLine("메타데이터: " + e.Message); } return L10n.Instance.English?sb.ToString().Replace("수정:","Modified:").Replace("프레임:","Frames:").Replace("카메라:","Camera:").Replace("촬영일:","Date taken:").Replace("제목:","Title:").Replace("저작권:","Copyright:").Replace("메타데이터:","Metadata:"):sb.ToString(); }
    static void Walk(BitmapMetadata m, string prefix, StringBuilder sb, HashSet<string> seen, int depth) { if (depth > 6) return; foreach (string q in m) { try { var v = m.GetQuery(q); string name = prefix + q; if (v is BitmapMetadata nested) Walk(nested, name, sb, seen, depth + 1); else if (v != null && seen.Add(name)) { string val = v is Array a ? string.Join(", ", a.Cast<object>().Take(40)) : v.ToString() ?? ""; if (val.Length > 500) val = val[..500]; sb.AppendLine(name + ": " + val); } } catch { } } }
    public static string[] RenameTargets(string[] sources, string pattern, int start) { if (string.IsNullOrWhiteSpace(pattern)) throw new ArgumentException(L10n.Choose("이름 패턴을 입력하세요.","Enter a filename pattern.")); var result = sources.Select((p, i) => Path.Combine(Path.GetDirectoryName(p)!, pattern.Replace("{name}", Path.GetFileNameWithoutExtension(p)).Replace("{n}", (start + i).ToString("D3")) + Path.GetExtension(p))).ToArray(); foreach (var p in result) { string name = Path.GetFileName(p); if (name.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0 || name.EndsWith(' ') || name.EndsWith('.') || Path.GetFileNameWithoutExtension(name).ToUpperInvariant() is "CON" or "PRN" or "AUX" or "NUL" || System.Text.RegularExpressions.Regex.IsMatch(name, @"^(COM|LPT)[1-9](\.|$)", System.Text.RegularExpressions.RegexOptions.IgnoreCase)) throw new ArgumentException(L10n.Choose("사용할 수 없는 파일 이름입니다: ","Invalid filename: ") + name); } if (result.Distinct(StringComparer.OrdinalIgnoreCase).Count() != result.Length) throw new ArgumentException(L10n.Choose("중복된 이름입니다. {n}을 넣으세요.","Duplicate names. Include {n} in the pattern.")); foreach (var p in result) if (File.Exists(p) && !sources.Contains(p, StringComparer.OrdinalIgnoreCase)) throw new IOException(L10n.Choose("이미 존재하는 파일: ","File already exists: ") + p); return result; }
    public static void Rename(string[] src, string[] dst) { var temp = src.Select(p => Path.Combine(Path.GetDirectoryName(p)!, ".mooview-" + Guid.NewGuid().ToString("N") + ".tmp")).ToArray(); int staged = 0, done = 0; try { for (; staged < src.Length; staged++) File.Move(src[staged], temp[staged]); for (; done < src.Length; done++) File.Move(temp[done], dst[done]); } catch { for (int i = done - 1; i >= 0; i--) File.Move(dst[i], temp[i]); for (int i = staged - 1; i >= 0; i--) File.Move(temp[i], src[i]); throw; } }
}

